import readline from "node:readline";
let initialized = false;
const send = value => process.stdout.write(`${JSON.stringify(value)}\n`);
readline.createInterface({ input: process.stdin }).on("line", line => {
  const request = JSON.parse(line);
  if (request.method === "initialize") return send({ jsonrpc: "2.0", id: request.id, result: { protocolVersion: request.params.protocolVersion, capabilities: { tools: {} }, serverInfo: { name: "quality", version: "1.0.0" } } });
  if (request.method === "notifications/initialized") { initialized = true; return; }
  if (request.id === undefined) return;
  if (!initialized) return send({ jsonrpc: "2.0", id: request.id, error: { code: -32603, message: "not initialized" } });
  if (request.method === "tools/list") return send({ jsonrpc: "2.0", id: request.id, result: { tools: [{ name: "echo_message", description: "Echo one message", inputSchema: { type: "object", properties: { message: { type: "string" } }, required: ["message"] }, annotations: { readOnlyHint: true } }] } });
  if (request.method === "tools/call") return send({ jsonrpc: "2.0", id: request.id, result: { content: [{ type: "text", text: request.params.arguments.message }] } });
  send({ jsonrpc: "2.0", id: request.id, error: { code: -32601, message: "unsupported" } });
});
